uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// User Parameters
uniform float u_speed;
uniform float u_scale;
uniform float u_sparkle;
uniform float u_glow;
uniform float u_hue;   // Bottom Color
uniform float u_hue2;  // Top Color

// New AI Aesthetic Parameters
uniform float u_neuro_complexity; // Chaos/Fractal detail
uniform float u_chromatic_aberration; // Color fringing
uniform float u_bass; // Audio Reactivity
uniform float u_glitch_intensity; // Subtle digital artifacts

// "Mad" Parameters
uniform float u_rage_intensity; // Shaking and jaggedness
uniform float u_distortion_warp; // Geometry warping

out vec4 fragColor;

// --- Helper Functions ---

float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// 2D Rotation matrix
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Pseudo-fractal noise for that "AI/Neural" look
float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    for (int i = 0; i < 4; ++i) {
        v += a * (sin(p.x) + sin(p.y));
        p = rot(0.5 + u_rage_intensity * 0.2) * p * (2.0 + u_bass) + shift;
        a *= 0.5;
    }
    return v;
}

// HSB to RGB Conversion
vec3 hsb2rgb(vec3 c) {
    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

// Dual-Hue Palette Logic
vec3 getLayerColor(int i, float hue1, float hue2) {
    float t = float(i) / 9.0; 
    float h = mix(hue1, hue2, t);
    // When "Mad", shift towards red/angry tones
    h = mix(h, 0.0, u_rage_intensity * 0.5); 
    float sat = mix(0.8, 1.0, u_rage_intensity);
    float bri = mix(0.4, 1.2, t);
    return hsb2rgb(vec3(h, sat, bri));
}

float getDust(vec2 uv, float t) {
    float gridSize = 25.0 + u_rage_intensity * 20.0; 
    vec2 id = floor(uv * gridSize);
    vec2 f = fract(uv * gridSize);
    float r = hash(id);
    vec2 pos = vec2(r, fract(r * 12.34));
    float d = distance(f, pos);
    float size = 0.03 * (0.5 + 0.5 * sin(t * (5.0 + u_rage_intensity * 10.0) + r * 15.0));
    return smoothstep(size, size * 0.5, d) * r; 
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // "Mad" Screen Shake
    float shake = hash(vec2(iTime, 0.0)) * u_rage_intensity * 0.05;
    uv += vec2(shake, -shake);

    vec2 uv0 = uv;

    // Fluid time mapping (Removed freeze-check logic)
    float spd = u_speed;
    float time = iTime * spd;
    float scale = u_scale;
    float sparkleInt = u_sparkle;
    float glowInt = u_glow;

    // Colors
    float hue1 = u_hue; 
    float hue2 = u_hue2;

    // Apply Neural Distortions to UV for "AI Dream" look
    float neural = fbm(uv * (3.0 + u_distortion_warp) + time * 0.2) * (u_neuro_complexity + u_rage_intensity);
    uv += neural * (0.1 + u_distortion_warp * 0.1);

    // Background: Dark blend with a hint of neural noise - shifts redder as rage increases
    vec3 bgCol = hsb2rgb(vec3(mix(hue1, hue2, 0.5), 0.8 + u_rage_intensity * 0.2, 0.02 + neural * 0.02));
    vec3 finalColor = bgCol;

    // Chromatic Aberration offsets - amplified by madness
    float ca = (u_chromatic_aberration + u_rage_intensity * 0.5) * 0.04;

    // Multi-pass rendering for the layers
    for(int i = 0; i < 10; i++) {
        float layerIndex = float(i);

        // --- Wave Logic with Neural Morphing ---
        float freq = (1.5 + layerIndex * 0.1) * (1.0 + u_rage_intensity);
        float waveHeight = sin(uv.x * freq + time * (1.0 + u_rage_intensity) + layerIndex) * 0.3; 

        // Jagged artifacts added for "mad" look
        waveHeight += abs(sin(uv.x * 20.0 + time * 2.0)) * 0.05 * u_rage_intensity;
        waveHeight += sin(uv.x * 4.0 - time * 1.2 + layerIndex) * 0.05; 

        // Mix in fbm for "generative" fluid movement
        waveHeight += fbm(vec2(uv.x * 2.0, time * 0.5)) * 0.1 * (u_neuro_complexity + u_rage_intensity);
        waveHeight *= scale;

        float yOffset = -0.7 + (layerIndex * 0.15); 
        float surfaceY = waveHeight + yOffset;

        // Mask
        float fillMask = smoothstep(0.01, -0.01, uv.y - surfaceY);

        // Glow with simulated chromatic aberration
        float edgeDist = abs(uv.y - surfaceY);
        float edgeGlowR = exp(-abs(uv.y - (surfaceY + ca)) * 10.0) * glowInt * (1.0 + u_rage_intensity);
        float edgeGlowG = exp(-edgeDist * 10.0) * glowInt;
        float edgeGlowB = exp(-abs(uv.y - (surfaceY - ca)) * 10.0) * glowInt;

        // --- Color Logic ---
        vec3 col = getLayerColor(i, hue1, hue2);

        // Add Audio Reactivity
        col *= (1.0 + u_bass * 0.8);

        // --- Sparkles ---
        vec2 dustUV = uv;
        dustUV.x -= time * 0.1 + (layerIndex * 0.03); 
        float sparkles = getDust(dustUV + vec2(layerIndex, 0.0), time);

        // --- Composition ---
        finalColor += col * fillMask * 0.12; 
        finalColor.r += col.r * edgeGlowR * 0.5;
        finalColor.g += col.g * edgeGlowG * 0.5;
        finalColor.b += col.b * edgeGlowB * 0.5;

        vec3 sparkleCol = mix(col, vec3(1.0, 0.2, 0.2), u_rage_intensity);
        finalColor += sparkleCol * sparkles * fillMask * sparkleInt;
    }



    // Vignette - tightens when mad
    finalColor *= (1.2 + u_rage_intensity * 0.5) - length(uv0) * (0.6 + u_rage_intensity * 0.6);

    // Final AI Polish: Contrast and Tone Mapping
    finalColor = pow(finalColor, vec3(0.9 - u_rage_intensity * 0.4)); 
    finalColor = smoothstep(-0.05, 1.15 + u_rage_intensity * 0.5, finalColor);

    fragColor = vec4(finalColor, 1.0);
}

